screenPanels.initJs:
function(container, apiUrl, tables) {
  const monthInput = container.querySelector('[data-testid="target-month-input"]');
  const strategySelect = container.querySelector('[data-testid="strategy-select"]');
  const plannedStaffInput = container.querySelector('[data-testid="planned-staff-input"]');
  const targetProductivityInput = container.querySelector('[data-testid="target-productivity-input"]');
  const scenarioNameInput = container.querySelector('[data-testid="scenario-name-input"]');
  const simulateBtn = container.querySelector('[data-testid="simulate-btn"]');
  const createScenarioBtn = container.querySelector('[data-testid="create-scenario-btn"]');
  const exportBtn = container.querySelector('[data-testid="export-btn"]');
  const patternTbody = container.querySelector('#pattern-tbody');
  const productivityTbody = container.querySelector('#productivity-tbody');
  const scenarioTbody = container.querySelector('#scenario-tbody');
  const simulationResult = container.querySelector('#simulation-result');
  const noResult = container.querySelector('#no-result');
  const scenarioDetailModal = container.querySelector('#scenario-detail-modal');
  const closeModalBtn = container.querySelector('[data-testid="close-modal-btn"]');
  const modalCloseBtn = container.querySelector('[data-testid="modal-close-btn"]');
  const modalApplyBtn = container.querySelector('[data-testid="modal-apply-btn"]');

  // 初期月を今月に設定
  const today = new Date();
  const year = today.getFullYear();
  const month = String(today.getMonth() + 1).padStart(2, '0');
  monthInput.value = `${year}-${month}`;

  // モーダル閉じる処理
  const closeModal = () => {
    scenarioDetailModal.style.display = 'none';
  };
  closeModalBtn.addEventListener('click', closeModal);
  modalCloseBtn.addEventListener('click', closeModal);
  scenarioDetailModal.addEventListener('click', (e) => {
    if (e.target === scenarioDetailModal) closeModal();
  });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && scenarioDetailModal.style.display !== 'none') closeModal();
  });

  // データ取得・表示
  async function loadData() {
    const targetMonth = monthInput.value;
    if (!targetMonth) return;

    // 月次査定件数データ取得
    const monthlyData = await window.aivicApi.list(6); // 月次査定件数テーブル
    const patternData = await window.aivicApi.list(7); // 変動パターンテーブル
    const productivityData = await window.aivicApi.list(5); // 査定員生産性テーブル
    const scenarioData = await window.aivicApi.list(10); // 人員配置シナリオテーブル
    const planData = await window.aivicApi.list(8); // 人員配置計画テーブル

    if (!monthlyData || !patternData || !productivityData) return;

    // KPI 更新
    const currentMonthData = monthlyData.find(m => m.対象年月 === targetMonth);
    const currentPlan = planData?.find(p => p.計画年月 === targetMonth);
    const currentPattern = patternData.find(p => p.是否 === true);

    container.querySelector('[data-testid="kpi-estimate-count"]').textContent = 
      currentMonthData?.査定件数 || '-';
    container.querySelector('[data-testid="kpi-recommended-staff"]').textContent = 
      currentPattern?.推奨人員数 || '-';
    container.querySelector('[data-testid="kpi-volatility"]').textContent = 
      currentPattern?.変動係数 || '-';
    container.querySelector('[data-testid="kpi-current-staff"]').textContent = 
      currentPlan?.実績査定員数 || currentPlan?.計画査定員数 || '-';

    // グラフ描画
    drawChart(monthlyData, targetMonth);

    // 変動パターン一覧
    patternTbody.innerHTML = patternData.map(p => `
      <tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 6px; color: var(--text);">${p.パターン名 || '-'}</td>
        <td style="padding: 6px; text-align: center; color: var(--text);">${p.変動係数 || '-'}</td>
        <td style="padding: 6px; text-align: center; color: var(--text);">${p.推奨人員数 || '-'}</td>
      </tr>
    `).join('');

    // 査定員別生産性
    const monthProductivity = productivityData.filter(p => p.対象年月 === targetMonth);
    productivityTbody.innerHTML = monthProductivity.slice(0, 5).map(p => `
      <tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 4px; color: var(--text);">査定員${p.査定員ID?.slice(0, 4) || '-'}</td>
        <td style="padding: 4px; text-align: center; color: var(--text);">${p.見積件数 || '-'}</td>
        <td style="padding: 4px; text-align: center; color: var(--text);">${p.生産性スコア || '-'}</td>
      </tr>
    `).join('');

    // シナリオ一覧
    const monthScenarios = scenarioData?.filter(s => s.対象年月 === targetMonth) || [];
    scenarioTbody.innerHTML = monthScenarios.map(s => `
      <tr style="border-bottom: 1px solid var(--border);" data-scenario-id="${s.シナリオID}">
        <td style="padding: 6px; color: var(--text);">${s.シナリオ名 || '-'}</td>
        <td style="padding: 6px; text-align: center; color: var(--text);">${s.配置予定人数 || '-'}</td>
        <td style="padding: 6px; text-align: center; color: var(--text);">${s.予想総査定件数 || '-'}</td>
        <td style="padding: 6px; text-align: center; color: var(--text);">¥${(s.コスト見積額 || 0).toLocaleString()}</td>
        <td style="padding: 6px; text-align: center; color: var(--text);">${s.ステータス || '-'}</td>
        <td style="padding: 6px; text-align: center;">
          <button class="scenario-detail-btn" data-scenario-id="${s.シナリオID}" style="background: transparent; border: none; color: var(--primary); cursor: pointer; font-size: 11px; text-decoration: underline;">詳細</button>
        </td>
      </tr>
    `).join('');

    // シナリオ詳細ボタンリスナー
    container.querySelectorAll('.scenario-detail-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const scenarioId = e.target.dataset.scenarioId;
        const scenario = monthScenarios.find(s => s.シナリオID === scenarioId);
        if (scenario) {
          container.querySelector('#modal-content').innerHTML = `
            <div style="margin-bottom: 12px;">
              <div style="color: var(--text-muted); margin-bottom: 4px;">シナリオ名</div>
              <div style="font-weight: 600;">${scenario.シナリオ名 || '-'}</div>
            </div>
            <div style="margin-bottom: 12px;">
              <div style="color: var(--text-muted); margin-bottom: 4px;">説明</div>
              <div>${scenario.シナリオ説明 || '-'}</div>
            </div>
            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 12px;">
              <div>
                <div style="color: var(--text-muted); margin-bottom: 4px;">配置予定人数</div>
                <div style="font-weight: 600;">${scenario.配置予定人数 || '-'}</div>
              </div>
              <div>
                <div style="color: var(--text-muted); margin-bottom: 4px;">予想生産性</div>
                <div style="font-weight: 600;">${scenario.予想生産性 || '-'} 件/人/月</div>
              </div>
              <div>
                <div style="color: var(--text-muted); margin-bottom: 4px;">予想総査定件数</div>
                <div style="font-weight: 600;">${scenario.予想総査定件数 || '-'}</div>
              </div>
              <div>
                <div style="color: var(--text-muted); margin-bottom: 4px;">コスト見積額</div>
                <div style="font-weight: 600;">¥${(scenario.コスト見積額 || 0).toLocaleString()}</div>
              </div>
            </div>
            <div style="margin-bottom: 12px;">
              <div style="color: var(--text-muted); margin-bottom: 4px;">ステータス</div>
              <div style="font-weight: 600;">${scenario.ステータス || '-'}</div>
            </div>
          `;
          scenarioDetailModal.style.display = 'flex';
        }
      });
    });
  }

  // グラフ描画
  function drawChart(monthlyData, targetMonth) {
    const canvas = container.querySelector('#estimate-chart');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.fillStyle = '#eceff1';
    ctx.fillRect(0, 0, width, height);

    const last12Months = monthlyData.slice(-12);
    if (last12Months.length === 0) return;

    const maxValue = Math.max(...last12Months.map(m => m.査定件数 || 0), 100);
    const barWidth = width / last12Months.length;
    const padding = 20;

    ctx.strokeStyle = '#90a4ae';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    last12Months.forEach((m, i) => {
      const value = m.査定件数 || 0;
      const barHeight = (value / maxValue) * (height - 2 * padding);
      const x = padding + i * barWidth + barWidth * 0.1;
      const y = height - padding - barHeight;

      ctx.fillStyle = '#2c3e50';
      ctx.fillRect(x, y, barWidth * 0.8, barHeight);
    });
  }

  // シミュレーション実行
  simulateBtn.addEventListener('click', async () => {
    const strategy = strategySelect.value;
    const plannedStaff = parseInt(plannedStaffInput.value) || 0;
    const targetProductivity = parseInt(targetProductivityInput.value) || 0;

    if (!strategy || plannedStaff <= 0 || targetProductivity <= 0) {
      alert('すべての条件を入力してください');
      return;
    }

    const totalEstimate = plannedStaff * targetProductivity;
    const requiredStaff = Math.ceil(totalEstimate / targetProductivity);
    const costEstimate = requiredStaff * 300000; // 月額30万円/人と仮定

    container.querySelector('[data-testid="result-total-estimate"]').textContent = totalEstimate;
    container.querySelector('[data-testid="result-productivity"]').textContent = targetProductivity;
    container.querySelector('[data-testid="result-required-staff"]').textContent = requiredStaff;
    container.querySelector('[data-testid="result-cost"]').textContent = `¥${costEstimate.toLocaleString()}`;

    const evaluation = plannedStaff >= requiredStaff 
      ? '✓ 配置人数は十分です' 
      : `⚠ 配置人数が不足しています（必要: ${requiredStaff}名）`;
    container.querySelector('#result-evaluation').textContent = evaluation;

    simulationResult.style.display = 'block';
    noResult.style.display = 'none';

    // シナリオ保存
    if (scenarioNameInput.value) {
      const newScenario = {
        シナリオ名: scenarioNameInput.value,
        対象年月: monthInput.value,
        配置予定人数: plannedStaff,
        予想生産性: targetProductivity,
        予想総査定件数: totalEstimate,
        コスト見積額: costEstimate,
        ステータス: '案'
      };
      await window.aivicApi.save(10, newScenario);
      loadData();
    }
  });

  // シナリオ作成ボタン
  createScenarioBtn.addEventListener('click', () => {
    strategySelect.value = '';
    plannedStaffInput.value = '';
    targetProductivityInput.value = '';
    scenarioNameInput.value = '';
    simulationResult.style.display = 'none';
    noResult.style.display = 'block';
  });

  // エクスポートボタン
  exportBtn.addEventListener('click', async () => {
    const scenarioData = await window.aivicApi.list(10);
    if (!scenarioData) return;

    const csv = ['シナリオ名,対象年月,配置予定人数,予想生産性,予想総査定件数,コスト見積額,ステータス'];
    scenarioData.forEach(s => {
      csv.push(`${s.シナリオ名},${s.対象年月},${s.配置予定人数},${s.予想生産性},${s.予想総査定件数},${s.コスト見積額},${s.ステータス}`);
    });

    const bom = '\uFEFF';
    const blob = new Blob([bom + csv.join('\n')], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'scenarios.csv';
    link.click();
  });

  // 初期ロード
  monthInput.addEventListener('change', loadData);
  loadData();
}
